public static int findNthLeapYear(int Y, int N) {
    if (Y <= 0 || N <= 0) {
        throw new IllegalArgumentException("Both Y and N must be positive integers.");
    }
    int count = 0;
    int year = Y;
    while (true) {
        // Check if current year is a leap year
        if ((year % 4 == 0 && year % 100 != 0) || year % 400 == 0) {
            count++;
            if (count == N) {
                return year;
            }
        }
        // Prevent integer overflow
        if (year == Integer.MAX_VALUE) {
            throw new ArithmeticException("Reached the maximum integer value while searching for the Nth leap year.");
        }
        year++;
    }
}

