public List<List<Integer>> permute(int[] nums){
    java.util.List<List<Integer>> res = new java.util.ArrayList<>();
    int n = nums.length;
    if(n == 0){
        return res;
    }
    int[] a = java.util.Arrays.copyOf(nums, n);
    java.util.Arrays.sort(a);
    boolean hasNext = true;
    while(hasNext){
        java.util.List<Integer> temp = new java.util.ArrayList<>(n);
        for(int val : a){
            temp.add(val);
        }
        res.add(temp);
        int i = n - 2;
        while(i >= 0 && a[i] >= a[i+1]) i--;
        if(i < 0){
            hasNext = false;
            break;
        }
        int j = n - 1;
        while(a[j] <= a[i]) j--;
        int swap = a[i];
        a[i] = a[j];
        a[j] = swap;
        int l = i + 1, r = n - 1;
        while(l < r){
            int t = a[l];
            a[l] = a[r];
            a[r] = t;
            l++; r--;
        }
    }
    return res;
}

public int findLargestSubstring(List<String> strings) {
    if (strings == null || strings.isEmpty()) {
        return 0;
    }

    // Normalize null entries to empty strings
    List<String> processed = new ArrayList<>();
    for (String s : strings) {
        processed.add(s == null ? "" : s);
    }

    // Find the shortest string to minimize the search space
    String base = processed.get(0);
    for (String s : processed) {
        if (s.length() < base.length()) {
            base = s;
        }
    }

    int baseLen = base.length();
    // If the shortest string is empty, no non‑empty substring can satisfy the condition
    if (baseLen == 0) {
        return 0;
    }

    // Iterate lengths from longest to shortest
    for (int len = baseLen; len > 0; len--) {
        for (int start = 0; start + len <= baseLen; start++) {
            String sub = base.substring(start, start + len);
            String rev = new StringBuilder(sub).reverse().toString();

            boolean ok = true;
            for (String s : processed) {
                if (!(s.contains(sub) || s.contains(rev))) {
                    ok = false;
                    break;
                }
            }

            if (ok) {
                return len; // Found the longest valid substring length
            }
        }
    }

    return 0; // No substring (other than empty) satisfies the condition
}

public static int countOilDeposits(char[][] grid) {
    if (grid == null || grid.length == 0) {
        return 0;
    }

    int rows = grid.length;
    int cols = grid[0].length;

    // Validate each row for nullness and uniform length
    for (int r = 0; r < rows; r++) {
        if (grid[r] == null || grid[r].length != cols) {
            return 0; // Invalid input; return zero deposits
        }
    }

    boolean[][] visited = new boolean[rows][cols];
    int[] dr = {-1, -1, -1, 0, 0, 1, 1, 1};
    int[] dc = {-1, 0, 1, -1, 1, -1, 0, 1};

    int deposits = 0;

    for (int r = 0; r < rows; r++) {
        for (int c = 0; c < cols; c++) {
            if (grid[r][c] == '@' && !visited[r][c]) {
                deposits++;
                // Use a stack for depth-first search
                Deque<int[]> stack = new ArrayDeque<>();
                stack.push(new int[]{r, c});
                visited[r][c] = true;

                while (!stack.isEmpty()) {
                    int[] cell = stack.pop();
                    int cr = cell[0];
                    int cc = cell[1];

                    for (int d = 0; d < 8; d++) {
                        int nr = cr + dr[d];
                        int nc = cc + dc[d];
                        if (nr >= 0 && nr < rows && nc >= 0 && nc < cols &&
                            !visited[nr][nc] && grid[nr][nc] == '@') {
                            visited[nr][nc] = true;
                            stack.push(new int[]{nr, nc});
                        }
                    }
                }
            }
        }
    }

    return deposits;
}

