}

public int search(int[] nums, int target) {
    if (nums == null || nums.length == 0) {
        return -1;
    }
    int left = 0;
    int right = nums.length - 1;
    while (left <= right) {
        int mid = left + (right - left) / 2;
        if (nums[mid] == target) {
            return mid;
        }
        // Determine which side is normally ordered
        if (nums[left] <= nums[mid]) { // left half is sorted
            if (nums[left] <= target && target < nums[mid]) {
                right = mid - 1;
            } else {
                left = mid + 1;
            }
        } else { // right half is sorted
            if (nums[mid] < target && target <= nums[right]) {
                left = mid + 1;
            } else {
                right = mid - 1;
            }
        }
    }
    return -1;
}

public double trimMean(int[] arr) {
    if (arr == null || arr.length == 0) {
        return 0.0;
    }
    int n = arr.length;
    int removeCount = (int) Math.floor(n * 0.05); // 5% of n, integer
    int[] sorted = arr.clone();
    java.util.Arrays.sort(sorted);
    long sum = 0;
    for (int i = removeCount; i < n - removeCount; i++) {
        sum += sorted[i];
    }
    int remaining = n - 2 * removeCount;
    return sum / (double) remaining;
}

public boolean canArrange(int[] arr, int k) {
    if (arr == null || k == 0) {
        return false; // invalid divisor
    }
    if (arr.length % 2 != 0) {
        return false; // cannot pair odd number of elements
    }
    int[] freq = new int[k];
    for (int num : arr) {
        int mod = ((num % k) + k) % k;
        freq[mod]++;
    }
    // Check remainder 0
    if (freq[0] % 2 != 0) {
        return false;
    }
    // Check other remainders
    for (int r = 1; r <= k / 2; r++) {
        int complement = k - r;
        if (r == complement) { // occurs when k is even and r == k/2
            if (freq[r] % 2 != 0) {
                return false;
            }
        } else {
            if (freq[r] != freq[complement]) {
                return false;
            }
        }
    }
    return true;
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    @SuppressWarnings("unchecked")
    List<Integer>[] graph = new ArrayList[n];
    for (int i = 0; i < n; i++) graph[i] = new ArrayList<>();
    for (int[] e : edges) {
        graph[e[0]].add(e[1]);
        graph[e[1]].add(e[0]);
    }
    int[] time = new int[1];
    dfs(0, -1, graph, hasApple, time);
    return time[0];
}

private boolean dfs(int node, int parent, List<Integer>[] graph, boolean[] hasApple, int[] time) {
    boolean need = hasApple[node];
    for (int nei : graph[node]) {
        if (nei == parent) continue;
        if (dfs(nei, node, graph, hasApple, time)) {
            time[0] += 2;
            need = true;
        }
    }
    return need;
}

public String sortString(String s) {
    if (s == null || s.isEmpty()) {
        return "";
    }
    java.util.TreeMap<Character, Integer> map = new java.util.TreeMap<>();
    for (char c : s.toCharArray()) {
        map.put(c, map.getOrDefault(c, 0) + 1);
    }
    StringBuilder result = new StringBuilder();
    while (!map.isEmpty()) {
        // Ascending phase
        Character last = null;
        boolean first = true;
        while (true) {
            if (first) {
                java.util.Map.Entry<Character, Integer> e = map.firstEntry();
                if (e == null) break;
                char c = e.getKey();
                result.append(c);
                if (e.getValue() == 1) {
                    map.remove(c);
                } else {
                    map.put(c, e.getValue() - 1);
                }
                last = c;
                first = false;
            } else {
                java.util.Map.Entry<Character, Integer> e = map.higherEntry(last);
                if (e == null) break;
                char c = e.getKey();
                result.append(c);
                if (e.getValue() == 1) {
                    map.remove(c);
                } else {
                    map.put(c, e.getValue() - 1);
                }
                last = c;
            }
        }
        // Descending phase
        last = null;
        first = true;
        while (true) {
            if (first) {
                java.util.Map.Entry<Character, Integer> e = map.lastEntry();
                if (e == null) break;
                char c = e.getKey();
                result.append(c);
                if (e.getValue() == 1) {
                    map.remove(c);
                } else {
                    map.put(c, e.getValue() - 1);
                }
                last = c;
                first = false;
            } else {
                java.util.Map.Entry<Character, Integer> e = map.lowerEntry(last);
                if (e == null) break;
                char c = e.getKey();
                result.append(c);
                if (e.getValue() == 1) {
                    map.remove(c);
                } else {
                    map.put(c, e.getValue() - 1);
                }
                last = c;
            }
        }
    }
    return result.toString();
}

public boolean splitArraySameAverage(int[] nums) {
    if (nums == null || nums.length < 2) {
        return false;
    }
    int n = nums.length;
    long total = 0;
    for (int num : nums) {
        total += num;
    }
    int half = n / 2;
    @SuppressWarnings("unchecked")
    HashSet<Integer>[] dp = new HashSet[half + 1];
    for (int i = 0; i <= half; i++) {
        dp[i] = new HashSet<>();
    }
    dp[0].add(0);
    int count = 0;
    for (int num : nums) {
        int maxK = Math.min(count, half - 1);
        for (int k = maxK; k >= 0; k--) {
            for (int sum : dp[k]) {
                dp[k + 1].add(sum + num);
            }
        }
        count++;
    }
    for (int k = 1; k <= half; k++) {
        if ((total * k) % n != 0) {
            continue;
        }
        int target = (int) ((total * k) / n);
        if (dp[k].contains(target)) {
            return true;
        }
    }
    return false;
}

public int minCostClimbingStairs(int[] cost) {
    try {
        if (cost == null || cost.length == 0) {
            return 0;
        }
        int n = cost.length;
        if (n == 1) {
            // Only one step, we can start above it with no cost
            return 0;
        }
        int prevTwo = cost[0];
        int prevOne = cost[1];
        for (int i = 2; i < n; i++) {
            int current = cost[i] + Math.min(prevOne, prevTwo);
            prevTwo = prevOne;
            prevOne = current;
        }
        return Math.min(prevOne, prevTwo);
    } catch (Exception e) {
        // In case of unexpected errors, return 0 as a safe fallback
        return 0;
    }
}

public int uniqueMorseRepresentations(String[] words) {
    if (words == null || words.length == 0) {
        return 0;
    }

    String[] morse = { ".-", "-...", "-.-.", "-..", ".", "..-.", "--.", "....", "..", ".---",
                       "-.-", ".-..", "--", "-.", "---", ".--.", "--.-", ".-.", "...",
                       "-", "..-", "...-", ".--", "-..-", "-.--", "--.." };

    java.util.Set<String> unique = new java.util.HashSet<>();

    for (String word : words) {
        if (word == null) {
            continue; // skip null entries
        }
        StringBuilder sb = new StringBuilder();
        for (char c : word.toCharArray()) {
            if (c >= 'a' && c <= 'z') {
                sb.append(morse[c - 'a']);
            } else if (c >= 'A' && c <= 'Z') {
                sb.append(morse[c - 'A']);
            } else {
                // ignore non-letter characters
            }
        }
        unique.add(sb.toString());
    }

    return unique.size();
}

public boolean hasAllCodes(String s, int k) {
    // Basic validation
    if (s == null || k <= 0 || s.length() < k) {
        return false;
    }
    // Ensure k is within manageable bounds to avoid excessive array size
    if (k >= 31) { // 2^k would overflow int and array would be too large
        return false;
    }
    int totalCodes = 1 << k;          // Number of distinct binary strings of length k
    boolean[] seen = new boolean[totalCodes];
    int seenCount = 0;
    int mask = totalCodes - 1;        // Mask to keep only k bits
    int code = 0;
    for (int i = 0; i < s.length(); i++) {
        // Build the current k-bit window
        code = ((code << 1) & mask) | (s.charAt(i) - '0');
        if (i >= k - 1) { // enough characters to have a full window
            if (!seen[code]) {
                seen[code] = true;
                seenCount++;
                if (seenCount == totalCodes) {
                    return true; // All possible codes found
                }
            }
        }
    }
    return false; // Not all codes appeared
}

