public int minInsertions(String s) {
    if (s == null) {
        return 0;
    }
    int insertions = 0;
    int balance = 0; // number of unmatched '('
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c == '(') {
            balance++;
        } else if (c == ')') {
            if (balance > 0) {
                balance--;
            } else {
                // need a '(' before this ')'
                insertions++;
                // after inserting, the ')' is matched immediately, so balance stays 0
            }
        } else {
            // for safety, ignore unexpected characters
        }
    }
    // close any remaining unmatched '('
    insertions += balance;
    return insertions;
}

public int minOperations(int n) {
    if (n <= 0) {
        throw new IllegalArgumentException("n must be positive");
    }
    if ((n & 1) == 0) { // even
        int k = n / 2;
        return k * k;
    } else { // odd
        int k = (n - 1) / 2;
        return k * (k + 1);
    }
}

