public int maxAbsoluteSum(int[] nums) {
    if (nums == null) {
        throw new IllegalArgumentException("Input array cannot be null.");
    }
    int n = nums.length;
    if (n == 0) {
        return 0;
    }

    int maxEnding = nums[0];
    int maxSoFar = nums[0];
    int minEnding = nums[0];
    int minSoFar = nums[0];

    for (int i = 1; i < n; i++) {
        int val = nums[i];

        // Kadane for maximum subarray sum
        maxEnding = Math.max(val, maxEnding + val);
        maxSoFar = Math.max(maxSoFar, maxEnding);

        // Kadane for minimum subarray sum (most negative)
        minEnding = Math.min(val, minEnding + val);
        minSoFar = Math.min(minSoFar, minEnding);
    }

    int maxAbs = Math.max(Math.abs(maxSoFar), Math.abs(minSoFar));
    return maxAbs;
}

public int findMinFibonacciNumbers(int k) {
    if (k <= 0) {
        throw new IllegalArgumentException("k must be greater than 0");
    }
    // Generate Fibonacci numbers up to k
    java.util.List<Integer> fib = new java.util.ArrayList<>();
    fib.add(1);
    fib.add(1);
    while (true) {
        int sz = fib.size();
        long next = (long) fib.get(sz - 1) + (long) fib.get(sz - 2);
        if (next > k) {
            break;
        }
        fib.add((int) next);
    }
    int count = 0;
    int remaining = k;
    // Greedy subtraction using the largest Fibonacci number each time
    while (remaining > 0) {
        // Find the largest Fibonacci number <= remaining
        for (int i = fib.size() - 1; i >= 0; i--) {
            int val = fib.get(i);
            if (val <= remaining) {
                remaining -= val;
                count++;
                break;
            }
        }
    }
    return count;
}

public int kthFactor(int n, int k) {
    if (n <= 0 || k <= 0) {
        return -1;
    }
    java.util.ArrayList<Integer> small = new java.util.ArrayList<>();
    java.util.ArrayList<Integer> large = new java.util.ArrayList<>();
    int limit = (int) Math.sqrt(n);
    for (int i = 1; i <= limit; i++) {
        if (n % i == 0) {
            small.add(i);
            int other = n / i;
            if (other != i) {
                large.add(other);
            }
        }
    }
    int totalFactors = small.size() + large.size();
    if (k > totalFactors) {
        return -1;
    }
    if (k <= small.size()) {
        return small.get(k - 1);
    } else {
        int indexInLarge = k - small.size() - 1;
        int reversedIndex = large.size() - 1 - indexInLarge;
        return large.get(reversedIndex);
    }
}

public String makeGood(String s) {
    if (s == null) {
        return "";
    }
    StringBuilder stack = new StringBuilder();
    try {
        for (char c : s.toCharArray()) {
            int len = stack.length();
            if (len > 0 && Math.abs(stack.charAt(len - 1) - c) == 32) {
                // The current character and the top of the stack cancel each other out
                stack.deleteCharAt(len - 1);
            } else {
                stack.append(c);
            }
        }
        return stack.toString();
    } catch (Exception e) {
        // In case of an unexpected runtime issue, return an empty string
        return "";
    }
}

public int maxUniqueSplit(String s) {
    if (s == null || s.isEmpty()) {
        return 0;
    }
    int n = s.length();
    int max = 0;
    int totalMasks = 1 << (n - 1); // there are n-1 possible split positions
    for (int mask = 0; mask < totalMasks; mask++) {
        Set<String> used = new HashSet<>();
        int start = 0;
        boolean valid = true;
        for (int i = 0; i < n - 1; i++) {
            if ((mask & (1 << i)) != 0) { // split after position i
                String sub = s.substring(start, i + 1);
                if (!used.add(sub)) {
                    valid = false;
                    break; // duplicate substring, this split invalid
                }
                start = i + 1;
            }
        }
        if (!valid) {
            continue;
        }
        // add the last substring
        String lastSub = s.substring(start, n);
        if (!used.add(lastSub)) {
            continue; // duplicate in last part
        }
        int count = used.size();
        if (count > max) {
            max = count;
        }
    }
    return max;
}

public int minOperations(String[] logs) {
    if (logs == null) {
        return 0;
    }
    java.util.Deque<String> stack = new java.util.ArrayDeque<>();
    for (String log : logs) {
        if (log.equals("../")) {
            if (!stack.isEmpty()) {
                stack.pop();
            }
        } else if (!log.equals("./")) {
            stack.push(log);
        }
    }
    return stack.size();
}

public String getSmallestString(int n, int k) {
    if (n <= 0) {
        throw new IllegalArgumentException("Length n must be positive.");
    }
    if (k < n || k > 26 * n) {
        throw new IllegalArgumentException("k must be between n and 26*n inclusive.");
    }
    char[] result = new char[n];
    for (int i = 0; i < n; i++) {
        result[i] = 'a';
    }
    int needed = k - n;
    int idx = n - 1;
    while (needed > 0 && idx >= 0) {
        int add = Math.min(25, needed);
        result[idx] = (char) ('a' + add);
        needed -= add;
        idx--;
    }
    return new String(result);
}

