public static int singleNumber(int[] nums) {
    if (nums == null || nums.length == 0) {
        return 0; // or throw IllegalArgumentException if preferred
    }
    int result = 0;
    for (int bit = 0; bit < 32; bit++) {
        int onesCount = 0;
        for (int num : nums) {
            if (((num >> bit) & 1) == 1) {
                onesCount++;
            }
        }
        result |= ((onesCount % 3) << bit);
    }
    return result;
}

public static List<Integer> findSteppingNumbers(int low, int high) {
    List<Integer> result = new ArrayList<>();
    try {
        if (low > high) {
            return result;
        }
        // Adjust lower bound for negative values
        if (low < 0) {
            low = 0;
        }
        // 0 is a stepping number
        if (low == 0 && 0 <= high) {
            result.add(0);
        }

        Queue<Long> queue = new LinkedList<>();
        // Start BFS from digits 1 to 9
        for (int d = 1; d <= 9; d++) {
            if (d > high) {
                break;
            }
            queue.offer((long) d);
        }

        while (!queue.isEmpty()) {
            long num = queue.poll();
            if (num >= low && num <= high) {
                result.add((int) num);
            }

            if (num > high / 10) { // appending another digit will exceed the range
                continue;
            }

            long lastDigit = num % 10;
            if (lastDigit > 0) {
                long next = num * 10 + (lastDigit - 1);
                if (next <= high) {
                    queue.offer(next);
                }
            }
            if (lastDigit < 9) {
                long next = num * 10 + (lastDigit + 1);
                if (next <= high) {
                    queue.offer(next);
                }
            }
        }

        Collections.sort(result);
    } catch (Exception e) {
        // In case of unexpected errors return the numbers found so far
        // or an empty list if none have been collected.
    }
    return result;
}

public static int countDigitOne(int n) {
    if (n <= 0) {
        return 0;
    }
    long count = 0;
    for (long factor = 1; factor <= n; ) {
        long lower = n % factor;
        long curr = (n / factor) % 10;
        long higher = n / (factor * 10);

        if (curr == 0) {
            count += higher * factor;
        } else if (curr == 1) {
            count += higher * factor + lower + 1;
        } else {
            count += (higher + 1) * factor;
        }

        if (factor > Long.MAX_VALUE / 10) {
            break; // Prevent overflow
        }
        factor *= 10;
    }
    return (int) count;
}

