public static int addDigits(int num) {
    if (num < 0) {
        throw new IllegalArgumentException("Input must be a non-negative integer");
    }
    while (num > 9) {
        int sum = 0;
        while (num > 0) {
            sum += num % 10;
            num /= 10;
        }
        num = sum;
    }
    return num;
}

public static int longestLine(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        return 0;
    }
    int m = mat.length;
    int n = mat[0].length;
    // dp[dir][i][j]: consecutive 1s ending at (i,j) in direction dir
    // dir 0: horizontal (left)
    // dir 1: vertical (up)
    // dir 2: diagonal (up-left)
    // dir 3: anti-diagonal (up-right)
    int[][][] dp = new int[4][m][n];
    int max = 0;
    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            if (mat[i][j] == 1) {
                dp[0][i][j] = (j > 0 ? dp[0][i][j - 1] : 0) + 1;           // horizontal
                dp[1][i][j] = (i > 0 ? dp[1][i - 1][j] : 0) + 1;           // vertical
                dp[2][i][j] = (i > 0 && j > 0 ? dp[2][i - 1][j - 1] : 0) + 1; // diagonal
                dp[3][i][j] = (i > 0 && j < n - 1 ? dp[3][i - 1][j + 1] : 0) + 1; // anti-diagonal
                int best = Math.max(
                        Math.max(dp[0][i][j], dp[1][i][j]),
                        Math.max(dp[2][i][j], dp[3][i][j])
                );
                if (best > max) {
                    max = best;
                }
            }
        }
    }
    return max;
}

public static String addThousandSeparator(int n) {
    // Handle zero explicitly to avoid adding any separators
    if (n == 0) {
        return "0";
    }

    // Preserve negative sign if present
    boolean isNegative = n < 0;
    long absValue = Math.abs((long) n);

    String absStr = Long.toString(absValue);
    StringBuilder sb = new StringBuilder();

    int count = 0;
    for (int i = absStr.length() - 1; i >= 0; i--) {
        sb.append(absStr.charAt(i));
        count++;
        // Insert dot after every three digits, but not at the end of the number
        if (count == 3 && i != 0) {
            sb.append('.');
            count = 0;
        }
    }

    sb.reverse();

    if (isNegative) {
        sb.insert(0, '-');
    }

    return sb.toString();
}

public static int largestRectangleArea(int[] heights) {
    if (heights == null || heights.length == 0) {
        return 0;
    }
    int n = heights.length;
    int[] stack = new int[n + 1];
    int top = -1;
    int maxArea = 0;
    for (int i = 0; i <= n; i++) {
        int currentHeight = (i == n) ? 0 : heights[i];
        while (top >= 0 && currentHeight < heights[stack[top]]) {
            int height = heights[stack[top--]];
            int width = (top == -1) ? i : i - stack[top] - 1;
            int area = height * width;
            if (area > maxArea) {
                maxArea = area;
            }
        }
        stack[++top] = i;
    }
    return maxArea;
}

public static int[] diagonalOrder(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        return new int[0];
    }
    int m = mat.length;
    int n = mat[0].length;
    int[] result = new int[m * n];
    int index = 0;
    for (int sum = 0; sum < m + n - 1; sum++) {
        int startRow = Math.max(0, sum - n + 1);
        int endRow = Math.min(m - 1, sum);
        if ((sum & 1) == 0) {
            for (int row = endRow; row >= startRow; row--) {
                int col = sum - row;
                result[index++] = mat[row][col];
            }
        } else {
            for (int row = startRow; row <= endRow; row++) {
                int col = sum - row;
                result[index++] = mat[row][col];
            }
        }
    }
    return result;
}

public static int findSmallestInteger(int n) {
    char[] digits = Integer.toString(n).toCharArray();
    int i = digits.length - 2;
    while (i >= 0 && digits[i] >= digits[i + 1]) {
        i--;
    }
    if (i < 0) {
        return -1;
    }
    int j = digits.length - 1;
    while (digits[j] <= digits[i]) {
        j--;
    }
    char temp = digits[i];
    digits[i] = digits[j];
    digits[j] = temp;
    int left = i + 1, right = digits.length - 1;
    while (left < right) {
        char t = digits[left];
        digits[left] = digits[right];
        digits[right] = t;
        left++;
        right--;
    }
    long value = 0;
    for (char c : digits) {
        value = value * 10 + (c - '0');
        if (value > Integer.MAX_VALUE) {
            return -1;
        }
    }
    return (int) value;
}

public static List<String> centerSymmetricNumbers(int n) {
    List<String> result = new ArrayList<>();
    if (n <= 0) {
        return result;
    }
    // Valid digit pairs for 180‑degree rotation
    char[][] pairs = {{'0', '0'}, {'1', '1'}, {'6', '9'}, {'8', '8'}, {'9', '6'}};
    char[] current = new char[n];
    generate(0, current, n, pairs, result);
    return result;
}

private static void generate(int pos, char[] current, int n, char[][] pairs, List<String> result) {
    // Stop when the first half (and middle if odd) is filled
    if (pos >= (n + 1) / 2) {
        // Leading zero is not allowed for numbers with more than one digit
        if (n > 1 && current[0] == '0') {
            return;
        }
        result.add(new String(current));
        return;
    }

    for (char[] pair : pairs) {
        char left = pair[0];
        char right = pair[1];

        // Skip leading zero for multi‑digit numbers
        if (pos == 0 && left == '0' && n > 1) {
            continue;
        }

        current[pos] = left;
        current[n - 1 - pos] = right;
        generate(pos + 1, current, n, pairs, result);
    }
}

public static boolean isBoomerang(int[][] points) {
    try {
        if (points == null || points.length != 3) {
            return false;
        }
        // Ensure each point has exactly two coordinates
        for (int[] p : points) {
            if (p == null || p.length != 2) {
                return false;
            }
        }
        // Check for duplicate points
        if ((points[0][0] == points[1][0] && points[0][1] == points[1][1]) ||
            (points[0][0] == points[2][0] && points[0][1] == points[2][1]) ||
            (points[1][0] == points[2][0] && points[1][1] == points[2][1])) {
            return false;
        }
        int x1 = points[0][0], y1 = points[0][1];
        int x2 = points[1][0], y2 = points[1][1];
        int x3 = points[2][0], y3 = points[2][1];
        // Use cross product to determine collinearity
        int cross = (x2 - x1) * (y3 - y1) - (x3 - x1) * (y2 - y1);
        return cross != 0;
    } catch (Exception e) {
        // If any unexpected issue occurs, treat as not a boomerang
        return false;
    }
}

public static int findNthUglyNumber(int n) {
    if (n <= 0) {
        throw new IllegalArgumentException("n must be a positive integer.");
    }
    if (n == 1) {
        return 1;
    }
    int[] ugly = new int[n];
    ugly[0] = 1;
    int i2 = 0, i3 = 0, i5 = 0;
    int next2 = 2, next3 = 3, next5 = 5;
    for (int i = 1; i < n; i++) {
        int nextUgly = Math.min(next2, Math.min(next3, next5));
        ugly[i] = nextUgly;
        if (nextUgly == next2) {
            i2++;
            next2 = ugly[i2] * 2;
        }
        if (nextUgly == next3) {
            i3++;
            next3 = ugly[i3] * 3;
        }
        if (nextUgly == next5) {
            i5++;
            next5 = ugly[i5] * 5;
        }
    }
    return ugly[n - 1];
}

public static int calculateEnergy(String s) {
    /*
     * Calculates the energy of the string, defined as the length of the longest
     * non‑empty contiguous substring that consists of a single repeated character.
     *
     * @param s the input string (can be null or empty)
     * @return the energy value (0 if the string is null or empty)
     */
    if (s == null || s.isEmpty()) {
        return 0;
    }
    int maxRun = 1;
    int currentRun = 1;
    for (int i = 1; i < s.length(); i++) {
        if (s.charAt(i) == s.charAt(i - 1)) {
            currentRun++;
        } else {
            if (currentRun > maxRun) {
                maxRun = currentRun;
            }
            currentRun = 1;
        }
    }
    if (currentRun > maxRun) {
        maxRun = currentRun;
    }
    return maxRun;
}

public static List<Integer> lexicalOrder(int n) {
    List<Integer> result = new ArrayList<>();
    if (n <= 0) {
        return result;
    }
    int cur = 1;
    for (int i = 0; i < n; i++) {
        result.add(cur);
        if (cur * 10 <= n) {
            cur *= 10;
        } else {
            while (cur % 10 == 9 || cur + 1 > n) {
                cur /= 10;
            }
            cur++;
        }
    }
    return result;
}

public static int calculateUniqueSum(int[] nums) {
    if (nums == null || nums.length == 0) {
        return 0;
    }
    java.util.Map<Integer, Integer> freq = new java.util.HashMap<>();
    for (int num : nums) {
        freq.merge(num, 1, Integer::sum);
    }
    int sum = 0;
    for (java.util.Map.Entry<Integer, Integer> entry : freq.entrySet()) {
        if (entry.getValue() == 1) {
            sum += entry.getKey();
        }
    }
    return sum;
}

public static int minPerfectSquareSum(int n) {
    if (n < 0) {
        throw new IllegalArgumentException("Input must be non-negative.");
    }
    if (n == 0) {
        return 0;
    }
    int[] dp = new int[n + 1];
    dp[0] = 0;
    int max = Integer.MAX_VALUE / 2;
    for (int i = 1; i <= n; i++) {
        dp[i] = max;
        for (int j = 1; j * j <= i; j++) {
            int square = j * j;
            dp[i] = Math.min(dp[i], dp[i - square] + 1);
        }
    }
    return dp[n];
}

public static String reverseWords(String s) {
    if (s == null) {
        return null;
    }
    int n = s.length();
    if (n == 0) {
        return s;
    }
    StringBuilder result = new StringBuilder(n);
    int wordStart = -1; // index of start of current word
    for (int i = 0; i < n; i++) {
        char c = s.charAt(i);
        if (c == ' ') {
            if (wordStart != -1) {
                // reverse the word from wordStart to i-1
                for (int j = i - 1; j >= wordStart; j--) {
                    result.append(s.charAt(j));
                }
                wordStart = -1;
            }
            result.append(' '); // keep the space
        } else {
            if (wordStart == -1) {
                wordStart = i; // start of a new word
            }
        }
    }
    // Append the last word if the string does not end with a space
    if (wordStart != -1) {
        for (int j = n - 1; j >= wordStart; j--) {
            result.append(s.charAt(j));
        }
    }
    return result.toString();
}
